"""Which agent sent each request. Pure state machine, no I/O.

Every agent is treated the same way: the proxy does not know or care whether
an agent is an orchestrator or a sub-agent, nor how agents are started.
It only uses facts of the Messages API protocol:

LLM requests
  * A request with no assistant message starts a new conversation = a new
    agent, even if its first message is identical to another agent's.
  * Every tool_use id is unique and generated by the API inside the response
    to one conversation. A request whose history contains tool_use ids belongs
    to the conversation that received them ("tool_chain", exact).
  * A request repeated after a failed first attempt (no successful response,
    nothing in flight) is a retry of the same conversation ("retry").
  * A continued conversation without any tool call so far falls back to the
    (container, metadata.user_id, first message) key ("first_message").

Other requests (web, package installs...)
  Tagged requests: inside the agent containers, a hook runs every shell command
  with proxy credentials naming its tool call (agent/sandbox/tag_tool_call.py),
  inherited by every process the command starts:
  * tag = a tool call the proxy saw     -> "tool_tag": the agent that received that
                                         tool_use (exact, background jobs included)
  * tag unknown to the proxy            -> "unknown_tag", agent_id None (suspicious)
  * the tagged command started other agents (e.g. `claude -p`), whose own
    requests inherit the tag: those agents' running tools are candidates too,
    resolved by content ("content_match") or left "ambiguous".
  Session tags: every process of an SSH login (aabs-...) or of a run launched from the
  dashboard (aabr-...) carries a session tag; the client's own requests (WebFetch...)
  carry it too. They are attributed by timing among that session's agents only.
  Untagged requests (requests made by the agent client itself, or a command that
  dropped its tag) fall back to timing:
  A tool runs between the response that emits its tool_use and the request
  that returns its tool_result. A non-LLM request from a container can only
  come from an agent of that container with a tool running at that moment.
  agent_id is set only when that is conclusive:
  * one such agent                    -> "single_running_agent"
  * several, and the running tools that
    mention the host belong to one     -> "content_match"
  * several, no unique match          -> "ambiguous", agent_id None
  * none running                      -> "no_running_tool", agent_id None
                                         (e.g. a background process)
  `candidates` always lists the agents that could have sent the request:
  the running ones, or for "no_running_tool" the agent whose tool started or
  ended last in that container.
"""
from __future__ import annotations

import hashlib
import re
import time
from collections import OrderedDict
from urllib.parse import parse_qsl, unquote, urlsplit
from dataclasses import dataclass, field

import anthropic_parse as ap

RUNNING_TOOL_TTL_S = 3600.0     # a tool call never answered is forgotten after this
RECENT_TOOL_WINDOW_S = 600.0    # fallback window when no tool is running
MAX_TOOL_OWNERS = 500_000


DOMAIN_RE = re.compile(r"(?<![\w.-])((?:[a-z0-9-]+\.)+[a-z]{2,})(?![\w-])")


def url_hints(host: str, url: str | None = None) -> set[str]:
    """Names that tie a request to the tool call that caused it: its host (also without
    "www."), and the domains its query string names (e.g. Claude Code's
    /api/web/domain_info?domain=example.com check before a WebFetch)."""
    h = (host or "").lower()
    hints = {h, h.removeprefix("www.")} - {""}
    for _, v in parse_qsl(urlsplit(url or "").query):
        hints |= set(DOMAIN_RE.findall(unquote(v).lower()))
    return hints


# Session tags: set by the sandbox for each SSH login (aabs-...) and each run launched from
# the dashboard (aabr-...), in the proxy credentials of every process of that session.
SESSION_TAG_RE = re.compile(r"aab[sr]-[A-Za-z0-9-]{1,100}")


def is_session_tag(tag: str | None) -> bool:
    return bool(tag) and SESSION_TAG_RE.fullmatch(tag) is not None


def mentions(info: dict, hints: set[str]) -> bool:
    return any(x in info["text"] for x in hints)


@dataclass
class AgentState:
    agent_id: str
    key: str
    client_ip: str | None
    in_flight: int = 0
    ok_calls: int = 0
    n_messages_logged: int = 0


@dataclass
class Attribution:
    agent_id: str | None
    tool_use_id: str | None
    method: str
    candidates: list[str] = field(default_factory=list)


def history_tool_use_ids(messages: list[dict]) -> list[str]:
    """tool_use ids in the assistant messages of a request, oldest first."""
    ids = []
    for m in messages:
        if m.get("role") == "assistant" and isinstance(m.get("content"), list):
            for b in m["content"]:
                if isinstance(b, dict) and b.get("type") in ("tool_use", "server_tool_use") and b.get("id"):
                    ids.append(b["id"])
    return ids


class AgentTracker:
    def __init__(self, clock=time.monotonic, boot_nonce: str | None = None):
        self.clock = clock
        # Distinguishes ids across proxy restarts (in-memory state is lost then).
        self.boot = boot_nonce if boot_nonce is not None else hashlib.sha256(
            str(time.time_ns()).encode()).hexdigest()[:8]
        self.agents: dict[str, AgentState] = {}
        self.by_key: dict[str, list[str]] = {}
        self.tool_owner: OrderedDict[str, str] = OrderedDict()
        self.running: dict[str, dict[str, dict]] = {}   # ip -> tool_use_id -> info
        self.recent: dict[str, list[dict]] = {}          # ip -> last client tool calls
        self.agent_tag: dict[str, str] = {}              # agent -> proxy tag its LLM calls carry

    # -- LLM requests -------------------------------------------------------
    def identify(self, ip: str | None, user_id: str | None,
                 messages: list[dict]) -> tuple[AgentState, str, bool]:
        """(agent, method, is_new) for a Messages API request."""
        for tid in reversed(history_tool_use_ids(messages)):
            aid = self.tool_owner.get(tid)
            if aid in self.agents:
                return self.agents[aid], "tool_chain", False

        key = hashlib.sha256("\x1f".join(
            [ip or "", user_id or "", ap.first_user_text(messages)]).encode()).hexdigest()
        same_key = self.by_key.get(key, [])
        started = any(m.get("role") == "assistant" for m in messages)
        if started and same_key:
            return self.agents[same_key[-1]], "first_message", False
        if not started:
            for aid in reversed(same_key):
                a = self.agents[aid]
                if a.ok_calls == 0 and a.in_flight == 0:
                    return a, "retry", False

        aid = hashlib.sha256(f"{self.boot}:{key}:{len(same_key)}".encode()).hexdigest()[:16]
        agent = AgentState(agent_id=aid, key=key, client_ip=ip)
        self.agents[aid] = agent
        self.by_key.setdefault(key, []).append(aid)
        return agent, "new_conversation", True

    def request_sent(self, agent: AgentState, messages: list[dict]) -> list[dict]:
        """Mark a request in flight; return the messages not logged yet for this agent
        and close the tool calls whose results it carries."""
        agent.in_flight += 1
        prev = agent.n_messages_logged
        delta = messages[prev:] if prev <= len(messages) else messages
        agent.n_messages_logged = len(messages)
        for r in ap.tool_results(messages):
            self._close(r["tool_use_id"])
        return delta

    def response_received(self, agent: AgentState, ok: bool,
                          tool_uses: list[dict]) -> None:
        agent.in_flight = max(0, agent.in_flight - 1)
        if ok:
            agent.ok_calls += 1
        t = self.clock()
        for tu in tool_uses:
            if not tu.get("id"):
                continue
            self.tool_owner[tu["id"]] = agent.agent_id
            if len(self.tool_owner) > MAX_TOOL_OWNERS:
                self.tool_owner.popitem(last=False)
            if tu.get("server"):
                continue  # executed by the API, not in the container
            info = {"t": t, "agent_id": agent.agent_id, "tool_use_id": tu["id"],
                    "text": str(tu.get("input")).lower()}
            self.running.setdefault(agent.client_ip or "", {})[tu["id"]] = info
            self._remember(agent.client_ip, info)

    def _remember(self, ip: str | None, info: dict) -> None:
        """Last tool events (start or end) per container, for the weak fallback."""
        rec = self.recent.setdefault(ip or "", [])
        rec.append({**info, "t": self.clock()})
        del rec[:-200]

    def _close(self, tool_use_id: str | None) -> None:
        if not tool_use_id:
            return
        for ip, tools in self.running.items():
            info = tools.pop(tool_use_id, None)
            if info:
                self._remember(ip, info)

    def running_tools(self, ip: str | None) -> list[dict]:
        """Tool calls currently running in a container (oldest first)."""
        tools = self.running.get(ip or "", {})
        t = self.clock()
        for tid in [k for k, v in tools.items() if t - v["t"] > RUNNING_TOOL_TTL_S]:
            del tools[tid]
        return sorted(tools.values(), key=lambda v: v["t"])

    def note_llm_tag(self, agent: AgentState, tag: str | None) -> None:
        """The agent's own API calls carry `tag`: its process was started by that tool call,
        or runs in that sandbox session (SSH login or dashboard run)."""
        if tag:
            self.agent_tag.setdefault(agent.agent_id, tag)

    # -- other requests -----------------------------------------------------
    def attribute(self, ip: str | None, host: str, tag: str | None = None,
                  url: str | None = None) -> Attribution:
        hints = url_hints(host, url)
        if tag and not is_session_tag(tag):
            owner = self.tool_owner.get(tag)
            if owner is None:
                return Attribution(None, None, "unknown_tag", [])
            inherited = [r for r in self.running_tools(ip)
                         if self.agent_tag.get(r["agent_id"]) == tag and r["agent_id"] != owner]
            if not inherited:
                return Attribution(owner, tag, "tool_tag", [owner])
            agents = [owner] + list(dict.fromkeys(r["agent_id"] for r in inherited))
            matches = [r for r in inherited if mentions(r, hints)]
            if matches and len({r["agent_id"] for r in matches}) == 1:
                return Attribution(matches[-1]["agent_id"], matches[-1]["tool_use_id"],
                                   "content_match", agents)
            return Attribution(None, None, "ambiguous", agents)

        # Untagged by a tool call: by timing, among the agents of the request's session when
        # it carries a session tag (else of the whole container).
        running = self.running_tools(ip)
        members = None
        if tag:   # no agent seen with this session tag yet: fall back to the container
            members = {a for a, t in self.agent_tag.items() if t == tag} or None
        if members is not None:
            running = [r for r in running if r["agent_id"] in members]
        agents = list(dict.fromkeys(r["agent_id"] for r in running))
        if len(agents) == 1:
            mine = [r for r in running if mentions(r, hints)] or running
            tid = mine[-1]["tool_use_id"] if len(mine) == 1 or mine is not running else None
            return Attribution(agents[0], tid, "single_running_agent", agents)
        if agents:
            matches = [r for r in running if mentions(r, hints)]
            if matches and len({r["agent_id"] for r in matches}) == 1:
                return Attribution(matches[-1]["agent_id"], matches[-1]["tool_use_id"],
                                   "content_match", agents)
            return Attribution(None, None, "ambiguous", agents)
        t = self.clock()
        rec = [r for r in self.recent.get(ip or "", []) if t - r["t"] <= RECENT_TOOL_WINDOW_S
               and (members is None or r["agent_id"] in members)]
        if rec:
            return Attribution(None, None, "no_running_tool", [rec[-1]["agent_id"]])
        return Attribution(None, None, "none", [])
